export const reportEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function reportDate(value){const d=new Date(value);return value&&!Number.isNaN(d.getTime())?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d):'未记录';}
export const reportStyles=`
*{box-sizing:border-box}html{color-scheme:light}body{margin:0;background:#eef1f6;color:#243249;font:14px/1.75 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}a{color:#2458c6;text-decoration:none;overflow-wrap:anywhere}p{margin:8px 0}h1,h2,h3{color:#182941;margin:0}h1{font-size:30px;line-height:1.35;letter-spacing:1px}h2{font-size:19px}h3{font-size:15px}.report-document{max-width:960px;margin:32px auto;background:#fff;box-shadow:0 8px 40px #20354f12}.report-masthead{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:25px 42px;border-bottom:1px solid #dbe3ef}.report-brand{font-size:23px;font-weight:800;letter-spacing:-.7px;color:#1c3153}.report-brand span{color:#2866e8}.report-masthead small{display:block;font-size:10px;color:#7c889c;font-weight:500;letter-spacing:2px}.report-edition{font-size:11px;letter-spacing:1.5px;color:#78869b;text-align:right}.report-cover{padding:32px 42px 24px;background:linear-gradient(120deg,#f0f5ff,#fff 75%);border-bottom:3px solid #2866e8}.report-eyebrow{font-size:11px;letter-spacing:2px;color:#3567c0;font-weight:700;margin-bottom:8px}.report-document-title{font-size:17px;font-weight:600;line-height:1.65;margin:16px 0 10px;overflow-wrap:anywhere}.report-badge{display:inline-block;padding:3px 10px;border:1px solid #bfcfe9;color:#345681;background:#f5f8fe;border-radius:4px;font-size:11px;vertical-align:middle}.report-demo{color:#865e18;border-color:#ead49b;background:#fff9e9}.report-content{padding:24px 42px 36px}.report-metadata{width:100%;border-collapse:collapse;font-size:12px;margin-top:18px}.report-metadata th,.report-metadata td{padding:7px 10px;border:1px solid #e0e7f1;text-align:left;overflow-wrap:anywhere;vertical-align:top}.report-metadata th{width:118px;background:#f7f9fc;font-weight:500;color:#63738b}.report-notice{padding:12px 15px;background:#f3f7ff;border-left:3px solid #5582db;font-size:12px;color:#52657f;line-height:1.85;margin:0 0 22px;overflow-wrap:anywhere}.report-panel{margin:24px 0;break-inside:auto}.report-section-title{display:flex;align-items:center;gap:10px;margin:0 0 14px;font-size:18px}.report-section-title:before{content:"";width:4px;height:18px;background:#2866e8;border-radius:2px;flex:none}.report-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:16px 0}.report-metric{padding:15px 14px;border:1px solid #e0e7f1;background:#fff;border-radius:6px;break-inside:avoid;min-width:0}.report-metric small{display:block;color:#6b7c94;font-size:12px}.report-metric strong{display:block;font-size:27px;line-height:1.5;color:#243b5b;font-variant-numeric:tabular-nums}.report-metric:first-child{background:#f5f8ff;border-color:#b9cdee}.report-metric:first-child strong{color:#2866e8}.report-metric em{font-style:normal;font-size:10px;color:#7c899d}.report-table{width:100%;border-collapse:collapse;font-size:12px;table-layout:fixed}.report-table th,.report-table td{padding:10px 12px;border:1px solid #dfe6f0;text-align:left;vertical-align:top;overflow-wrap:anywhere}.report-table th{background:#f3f6fb;font-weight:600;color:#536680}.report-table thead{display:table-header-group}.report-table tr{break-inside:avoid}.report-muted{color:#718199;font-size:12px}.report-text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:2;text-align:justify}.report-bar{height:5px;background:#e8edf5;border-radius:5px;overflow:hidden;margin-top:5px}.report-bar span{display:block;height:100%;background:#5480df}.report-legend{display:flex;gap:18px;flex-wrap:wrap;font-size:11px;color:#677990;margin:12px 0 20px}.report-legend i{display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:5px}.report-tag-risk{color:#a72f38;background:#fdecef}.report-tag-human{color:#22765f;background:#eaf7f1}.report-tag-unknown{color:#776a45;background:#f7f2e4}.report-tag-risk,.report-tag-human,.report-tag-unknown{border-radius:3px;padding:3px 7px;display:inline-block;font-size:11px}.report-empty{padding:20px;border:1px dashed #d9e2ef;background:#fbfcfe;color:#78869b;font-size:12px}.report-footer{border-top:1px solid #dfe6ef;margin:28px 0 0;padding:16px 0 0;display:flex;justify-content:space-between;gap:16px;font-size:10px;color:#8390a2}.report-evidence{border:1px solid #e0e7f1;margin:14px 0;border-radius:4px;overflow:hidden;break-inside:auto}.report-evidence-head{padding:10px 14px;background:#f5f7fb;border-bottom:1px solid #e0e7f1}.report-evidence-body{padding:12px 14px}.report-pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}.report-pair>div{min-width:0}.report-pair small{font-size:11px;color:#7d8ca2}.report-text mark,.report-inline-mark{background:#fff0ee;color:#b43838;border-bottom:1px solid #e9a4a0;padding:0 1px}.report-text mark.quoted{background:#eaf7f1;color:#22765f;border-color:#a1d9c4}.report-excluded{color:#8b95a5}.report-section-head{padding:9px 14px;background:#f4f7fc;border-left:3px solid #8da9da;margin:22px 0 12px;display:flex;justify-content:space-between;gap:12px}.report-paragraph{padding:0 0 16px}.report-paragraph-header{color:#7d8ca2;font-size:10px;margin-bottom:4px}.report-source-title{font-size:14px;line-height:1.8}.report-source-info{font-size:11px;color:#718199;line-height:1.8}.report-page-break{break-before:page}ol.report-notes{padding-left:20px;font-size:12px;color:#60718a}ol.report-notes li{margin:7px 0}
.aigc-report-part{margin:18px 0;break-inside:auto}.aigc-report-part-head{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.aigc-report-part-head h3{margin:8px 0}.aigc-report-text{padding:14px 18px;border-left:3px solid;white-space:pre-wrap;overflow-wrap:anywhere}.aigc-report-text-risk{border-color:#dc6a62;background:#fff4f2}.aigc-report-text-human{border-color:#35a788;background:#f0faf6}.aigc-report-text-unknown{border-color:#c49742;background:#fff9ed}.report-verdict{font-size:19px;font-weight:600;margin:15px 0}
@media(max-width:660px){.report-document{margin:0}.report-masthead{padding:20px}.report-cover,.report-content{padding:24px 20px}.report-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.report-pair{grid-template-columns:1fr}h1{font-size:24px}.report-metadata th{width:90px}.report-table th,.report-table td{padding:8px}.report-footer{flex-direction:column;gap:4px}}
@page{size:A4;margin:15mm 14mm;@bottom-left{content:"PaperKnow · 检测报告";font-size:8pt;color:#8792a4}@bottom-right{content:counter(page) " / " counter(pages);font-size:8pt;color:#8792a4}}
@media print{body{background:#fff;font-size:10pt}.report-document{max-width:none;margin:0;box-shadow:none}.report-masthead{padding:0 0 16px}.report-cover{padding:24px 0 20px;background:#fff}.report-content{padding:20px 0 0}.report-metrics{grid-template-columns:repeat(4,minmax(0,1fr))}.report-pair{grid-template-columns:1fr 1fr}.report-metadata,.report-table{font-size:9pt}.report-metric strong{font-size:22pt}h1{font-size:24pt}.report-panel h2,.report-section-head,.report-evidence-head{break-after:avoid}.report-source-title{break-after:avoid}.report-text{orphans:3;widows:3}.report-footer{display:none}a{color:#2458c6}}
/* Academic report hierarchy: summary, chapter statistics, sources and evidence. */
.report-navigation{display:flex;flex-wrap:wrap;border-bottom:1px solid #ccd5e0;padding:0 0 14px;margin:0 0 20px;gap:8px 20px;font-size:12px}.report-navigation a{color:#304c75}.report-cover{background:#fff;border-bottom:2px solid #274976}.report-metrics{gap:0;border:1px solid #cfd9e7}.report-metric{border:0;border-right:1px solid #dfe6f0;border-radius:0;min-width:0}.report-metric:last-child{border-right:0}.report-metric strong{font-size:25px}.report-metric em{display:block;overflow-wrap:anywhere;line-height:1.65}.report-section-title:before{background:#274976}.report-metric:first-child strong{color:#b72f3c}.report-table a{color:#304c75}.report-statistics th{width:27%}.report-statistics td{width:23%}.report-coverage-details{border-top:1px solid #dde4ed;margin-top:18px;padding-top:14px;font-size:12px;color:#52647c}.report-coverage-details summary{cursor:pointer}.report-table th{color:#30435e;background:#f1f4f8}.report-metadata th{color:#43546b}.report-evidence-body{line-height:1.9}.report-panel[id],.report-evidence[id]{scroll-margin-top:20px}.report-text mark{color:#b12432;background:#fff1f2}.aigc-report-text-risk{color:#a32c37}.report-section-title{break-after:avoid}.report-table caption{text-align:left;font-weight:600}
@media print{.report-navigation{display:none}.report-coverage-details:not([open]){display:none}.report-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}.report-metric strong{font-size:19pt}.report-metric small{font-size:8pt}.report-metric em{font-size:7pt}.report-metadata tr{break-inside:avoid}.report-evidence-body,.aigc-report-text{box-decoration-break:clone}.report-section-head h3{max-width:80%}}

.report-findings-table .report-text{margin:0;line-height:1.85}.report-locate-link{display:inline-block;margin-top:8px;font-weight:600}.report-comparison-caption{padding:10px 13px;background:#f4f7fb;font-size:12px;color:#526780}.report-comparison-caption a{float:right}.report-paragraph[id],.report-comparisons[id],.report-original-segment[id]{scroll-margin-top:18px}.report-paragraph:target,.report-comparisons:target,.report-original-segment:target{outline:2px solid #5682da;outline-offset:5px;background:#fffbea}.report-original-segment::before{content:attr(data-paragraph-label);font-size:11px;line-height:1.7;color:#4d6282;background:#fff;border:1px solid #dce5f2;border-radius:3px;padding:1px 5px;margin-right:5px;white-space:nowrap}.report-findings-table small{font-size:10px;color:#657790}.report-comparisons:empty{display:none}
@media print{.report-evidence[data-compact=true]{break-inside:avoid}.report-original-segment::before{font-size:8pt}.report-findings-table tr{break-inside:avoid}.report-comparison-caption a{float:none;margin-left:15px}.report-paragraph:target,.report-comparisons:target,.report-original-segment:target{outline:none}}
`;
/** summary/body are trusted generated markup. Document metadata is escaped here. */
export function reportDocument({title,type,id,createdAt,scope,metadata=[],navigation=[],summary='',body='',notice='',demo=false}){const esc=reportEscape,rows=[['报告编号',id||'未记录'],['检测时间',reportDate(createdAt)],['检测范围',scope||'未记录'],...metadata];return `<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'"><meta name="paperknow-report-version" content="2"><title>${esc(title)} · ${esc(type)} · PaperKnow</title><style>${reportStyles}</style></head><body><main class="report-document"><header class="report-masthead"><div class="report-brand">Paper<span>Know</span><small>让研究更清晰</small></div><div class="report-edition">PAPERKNOW RESEARCH INTEGRITY<br>检测报告 · 结果与依据</div></header><section class="report-cover"><p class="report-eyebrow">${demo?'DEMONSTRATION · 演示数据':'DETECTION REPORT · 检测报告'}</p><h1>${esc(type)}</h1><p class="report-document-title">${esc(title||'未命名文稿')}</p><span class="report-badge ${demo?'report-demo':''}">${demo?'演示报告 · 不用于实际结论':esc(scope||'检测范围未记录')}</span><table class="report-metadata"><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${esc(label)}</th><td>${esc(value??'未提供')}</td></tr>`).join('')}</tbody></table></section><div class="report-content">${navigation.length?`<nav class="report-navigation" aria-label="报告目录">${navigation.map(([id,label])=>`<a href="#${esc(id)}">${esc(label)}</a>`).join('')}</nav>`:''}${notice?`<p class="report-notice">${esc(notice)}</p>`:''}${summary}${body}<footer class="report-footer"><span>PaperKnow · ${esc(type)}</span><span>结果仅适用于本次记录的正文、范围与检测时间</span></footer></div></main></body></html>`;}
